/** Uses only an isolated workspace and generated JPEGs. */
public final class RollLifecycleInstrumentation extends Instrumentation {
    private static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);}
    interface Action{void run()throws Exception;}
    private static void reject(Action a)throws Exception{try{a.run();}catch(IllegalArgumentException|IllegalStateException|IOException expected){return;}throw new AssertionError("invalid operation accepted");}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){Bundle out=new Bundle();try{Context base=getTargetContext();check(base.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolated package");Context context=new WorkspaceContext(Workspace.root(base),UUID.randomUUID().toString());try(LogStore logs=new LogStore(context)){
        CatalogStore catalog=new CatalogStore(logs);String r=logs.addRoll("Lifecycle","Test400","Camera",400,36),other=logs.addRoll("Keep other","Test100","",100,36);for(int i=0;i<37;i++)logs.insert(r,10000+i*1000,0,480,"denied","","","","","","");
        reject(()->logs.saveLab(r,"active","send","Lab","","2026-10-27","","","35","CNY"));check(logs.roll(r).count==37&&logs.roll(r).state.equals("active"),"above36 remains active");logs.changeState(r,"active","finished","","","");
        reject(()->logs.saveLab(r,"finished","send","","","2026-10-27","","","35","CNY"));reject(()->logs.saveLab(r,"finished","send","Lab","","2026-02-30","","","35","CNY"));reject(()->logs.saveLab(r,"finished","send","Lab","","2026-10-27","","","-1","CNY"));check(logs.roll(r).state.equals("finished"),"invalid lab atomic");
        logs.saveLab(r,"finished","send","Lab","N1","2026-10-25","","Keep note","35","CNY");LogStore.Roll sent=logs.roll(r);check(sent.state.equals("developing")&&sent.sentDate.equals("2026-10-25")&&sent.labNotes.equals("Keep note")&&sent.labCost.equals("35"),"send saves metadata and state");
        reject(()->logs.saveLab(r,"developing","receive","Lab","N1","2026-10-25","2026-10-24","Keep note","35","CNY"));logs.saveLab(r,"developing","receive","Lab","N1","2026-10-25","2026-10-27","Keep note","40","CNY");logs.saveLab(r,"received","edit","Lab2","N2","2026-10-25","2026-10-27","changed","40","CNY");check(logs.roll(r).state.equals("received")&&logs.roll(r).lab.equals("Lab2"),"received edit preserves state");
        logs.costs(r,"12","40","CNY");reject(()->logs.saveLab(r,"received","edit","Lab2","N2","2026-10-25","2026-10-27","changed","40","USD"));check(logs.roll(r).currency.equals("CNY"),"no silent currency relabel");
        String own=logs.addRoll("Self","Test","",100,36);logs.insert(own,10000,0,480,"denied","","","","","","");logs.changeState(own,"active","finished","","","");logs.saveLab(own,"finished","send","自行冲洗","","2026-10-27","","own","","CNY");logs.changeState(own,"developing","finished","","","");check(logs.roll(own).lab.equals("自行冲洗")&&logs.roll(own).labCost.isEmpty(),"self/undo preserves unknown cost");
        String legacy=logs.addRoll("Legacy received","Test","",100,36);logs.getWritableDatabase().execSQL("UPDATE rolls SET state='received',lab='Legacy lab' WHERE id=?",new Object[]{legacy});logs.saveLab(legacy,"received","edit","Legacy lab","","","","","10","");check(logs.roll(legacy).sentDate.isEmpty()&&logs.roll(legacy).receivedDate.isEmpty()&&logs.roll(legacy).currency.isEmpty(),"editing legacy fees does not invent dates or currency");
        ByteArrayOutputStream backup=new ByteArrayOutputStream();FilmBackup.write(context,logs,backup);try(FilmBackup.Prepared prepared=FilmBackup.inspect(context,new ByteArrayInputStream(backup.toByteArray()))){check(prepared.manifest.getInt("schema")==25,"schema21");FilmBackup.restore(context,logs,prepared);int found=0;for(LogStore.Roll copy:logs.rolls())if(copy.receivedDate.equals("2026-10-27")&&copy.lab.equals("Lab2")&&copy.labNotes.equals("changed"))found++;check(found==2,"dates and notes roundtrip");prepared.manifest.put("schema",20);for(int i=0;i<prepared.manifest.getJSONArray("rolls").length();i++){JSONObject row=prepared.manifest.getJSONArray("rolls").getJSONObject(i);row.remove("lab_sent_date");row.remove("lab_received_date");row.remove("lab_notes");}FilmBackup.normalizeCatalog(prepared.manifest);check(prepared.manifest.getJSONArray("rolls").getJSONObject(0).getString("lab_sent_date").isEmpty(),"old backup no guessed dates");}
        String camera=catalog.saveCamera("","Nikon FE2","Keep camera","35 mm","","",false,"initial-Nikon");CatalogStore.Batch batch=new CatalogStore.Batch();batch.id="";batch.stock="Delete fixture";batch.format="35 mm";batch.iso=400;batch.capacity=36;batch.quantity=2;batch.threshold=0;batch.location=batch.temperature=batch.expiry=batch.purchaseDate=batch.price=batch.currency=batch.notes="";String batchId=catalog.saveBatch(batch,0);String loaded=catalog.load(batchId,UUID.randomUUID().toString(),"To delete",camera,""),returned=catalog.load(batchId,UUID.randomUUID().toString(),"Returned",camera,"");catalog.returnUnused(returned);
        String shot=logs.insert(loaded,10000,0,480,"denied","","","","","","");Bitmap bitmap=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE);ByteArrayOutputStream jpg=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,90,jpg);bitmap.recycle();File original=new File(context.getCacheDir(),"original-keep.jpg");try(OutputStream stream=new FileOutputStream(original)){stream.write(jpg.toByteArray());}
        ScanStore scans=new ScanStore(context,logs);ScanStore.Scan scan=scans.importJpeg(loaded,"scan",new ByteArrayInputStream(jpg.toByteArray()));scans.remove(loaded,scan.id);Bitmap ref=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);String token=UUID.randomUUID().toString();ReferencePhotos.capture(context,token,ref);ref.recycle();ReferencePhotos.record(context,logs,token,loaded,20000,0,480,"denied","","","","","","",null);String refId=token;
        int count=logs.roll(loaded).count;reject(()->logs.deleteRoll(loaded,count-1));check(scans.file(scan.id).exists()&&logs.roll(loaded).count==count,"stale deletion rejected");check(logs.deleteRoll(loaded,count),"private photos cleaned");check(!scans.file(scan.id).exists()&&!scans.file(refId).exists()&&original.exists(),"app copies removed; source kept");check(catalog.batch(batchId).quantity==1&&catalog.entry(camera,"camera").name.equals("Keep camera")&&logs.roll(other).count==0,"stock/camera/other roll kept");logs.deleteRoll(returned,0);check(catalog.batch(batchId).quantity==1,"deleting returned empty roll never double refunds");
        String racing=logs.addRoll("Race","Test","",100,36);InputStream input=new ByteArrayInputStream(jpg.toByteArray()){boolean deleted;@Override public synchronized int read(byte[] b,int o,int n){if(!deleted){deleted=true;logs.deleteRoll(racing,0);}return super.read(b,o,n);}};reject(()->scans.importJpeg(racing,"race",input));try(Cursor c=logs.getReadableDatabase().rawQuery("SELECT count(*) FROM scans WHERE roll_id=?",new String[]{racing})){c.moveToFirst();check(c.getInt(0)==0,"in-flight import cannot resurrect deleted roll");}
        backup.reset();FilmBackup.write(context,logs,backup);try(FilmBackup.Prepared prepared=FilmBackup.inspect(context,new ByteArrayInputStream(backup.toByteArray()))){FilmBackup.restore(context,logs,prepared);}check(catalog.history(batchId).contains("胶卷已删除"),"deleted-roll ledger remains readable and backup-valid");
        // Build a real v19 rolls table without the new columns, then exercise migration.
        String csv="id,roll_name,stock,camera,iso,frame_number,tapped_at_utc,captured_at_utc,offset_seconds,zone_offset_minutes,status,roll_id,roll_capacity,lab_sent_date,lab_received_date,lab_notes\n"+"csv-lab,CSV Lab,Test,Camera,400,1,2026-10-27T00:00:00Z,2026-10-27T00:00:00Z,0,480,denied,csv-r,36,2026-10-25,2026-10-27,keep lab note\n";
        CsvImport.Preview preview=CsvImport.parse(new StringReader(csv));JSONObject imported=preview.data.manifest.getJSONArray("rolls").getJSONObject(0);check(imported.getString("lab_sent_date").equals("2026-10-25")&&imported.getString("lab_notes").equals("keep lab note"),"CSV lab fields retained");preview.data.close();
        SQLiteDatabase db=logs.getWritableDatabase();String sql;try(Cursor c=db.rawQuery("SELECT sql FROM sqlite_master WHERE name='rolls'",null)){c.moveToFirst();sql=c.getString(0);}ArrayList<String> columns=new ArrayList<>();try(Cursor c=db.rawQuery("PRAGMA table_info(rolls)",null)){while(c.moveToNext())if(!c.getString(1).startsWith("lab_sent_")&&!c.getString(1).equals("lab_received_date")&&!c.getString(1).equals("lab_notes"))columns.add(c.getString(1));}db.beginTransaction();try{db.execSQL("ALTER TABLE rolls RENAME TO rolls20_fixture");db.execSQL(sql.replaceAll(",\\s*lab_(sent_date|received_date|notes) TEXT NOT NULL DEFAULT ''",""));String names=android.text.TextUtils.join(",",columns);db.execSQL("INSERT INTO rolls("+names+") SELECT "+names+" FROM rolls20_fixture");db.execSQL("DROP TABLE rolls20_fixture");db.setVersion(19);db.setTransactionSuccessful();}finally{db.endTransaction();}
    }
    try(LogStore migrated=new LogStore(context)){check(migrated.getReadableDatabase().getVersion()==24,"real19-to20 upgrade");for(LogStore.Roll r:migrated.rolls())check(r.sentDate.isEmpty()&&r.receivedDate.isEmpty()&&r.labNotes.isEmpty(),"no invented historical lab dates");}
    out.putString("stream","PASS: advisory37/36, rewind/send/self/receive/edit/undo; validation and atomic state; currency guard; schema21/legacy20/actual DB19 upgrade; stale delete, app photo cleanup, source/stock/camera preservation, returned roll deletion, ledger restore and in-flight import rejection\n");finish(-1,out);
    }catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));finish(0,out);}}
}
